cipal, require_principal\\n+from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n from aos_api.ecommerce_workshop_catalog import (\\n     EcommerceWorkshopCatalog,\\n     build_ecommerce_workshop_catalog,\\n@@ -394,6 +395,17 @@ def get_ecommerce_workshop_catalog() -> EcommerceWorkshopCatalog:\\n     return build_ecommerce_workshop_catalog()\\n \\n \\n+def get_ecommerce_workshop_read_catalog(\\n+    legacy: Annotated[EcommerceWorkshopCatalog, Depends(get_ecommerce_workshop_catalog)],\\n+) -> EcommerceWorkshopReadCatalog:\\n+    from aos_api.ecommerce_installed_readonly_catalog import build_installed_readonly_catalog\\n+\\n+    return EcommerceWorkshopReadCatalog(\\n+        legacy=legacy,\\n+        installed_factory=build_installed_readonly_catalog,\\n+    )\\n+\\n+\\n @lru_cache(maxsize=1)\\n def get_ecommerce_workshop_feature_activation_service() -> EcommerceWorkshopFeatureActivationService:\\n     return EcommerceWorkshopFeatureActivationService()\\n@@ -628,6 +640,9 @@ def get_ecommerce_operation_command_observation_service() -> EcommerceOperationC\\n CatalogDependency = Annotated[\\n     EcommerceWorkshopCatalog, Depends(get_ecommerce_workshop_catalog)\\n ]\\n+ReadCatalogDependency = Annotated[\\n+    EcommerceWorkshopReadCatalog, Depends(get_ecommerce_workshop_read_catalog)\\n+]\\n FeatureActivationServiceDependency = Annotated[\\n     EcommerceWorkshopFeatureActivationService,\\n     Depends(get_ecommerce_workshop_feature_activation_service),\\n@@ -1362,7 +1377,7 @@ def get_ecommerce_workshop_source_readiness_envelope(\\n def get_ecommerce_workshop_operations_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     operations: OperationsDependency,\\n ) -> WorkshopOperationsViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -1402,7 +1417,7 @@ def get_ecommerce_operation_case_workspace_view(\\n def get_ecommerce_workshop_content_campaign_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     content_campaign: ContentCampaignDependency,\\n ) -> WorkshopContentCampaignViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -1489,7 +1504,7 @@ def preview_ecommerce_content_campaign_approval(\\n def get_ecommerce_workshop_creator_growth_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     creator_growth: CreatorGrowthDependency,\\n ) -> WorkshopCreatorGrowthViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -1771,7 +1786,7 @@ def get_creator_lifecycle_view(\\n def get_ecommerce_workshop_media_studio_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     media_studio: MediaStudioDependency,\\n ) -> WorkshopMediaStudioViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -1949,7 +1964,7 @@ def get_ecommerce_workshop_media_studio_full_production_scenario(\\n def get_ecommerce_workshop_analyst_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     analyst: AnalystDependency,\\n ) -> WorkshopAnalystViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -1986,7 +2001,7 @@ def get_ecommerce_workshop_analyst_learning_scenario(\\n def get_ecommerce_workshop_price_governance_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     price_governance: PriceGovernanceDependency,\\n ) -> WorkshopPriceGovernanceViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -2301,7 +2316,7 @@ def get_price_disposition_contribution_view(\\n def get_ecommerce_workshop_customer_view(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     customer: CustomerDependency,\\n ) -> WorkshopCustomerViewEnvelope:\\n     _reject_query_parameters(request)\\n@@ -2888,7 +2903,7 @@ def kill_ecommerce_operation_automation(\\n def get_ecommerce_workshop_task_cockpit_core(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     cockpit: TaskCockpitDependency,\\n     status: Annotated[TaskStatus | None, Query()] = None,\\n     limit: Annotated[int, Query(ge=1, le=100)] = 50,\\n\", \".evidence/qyh-eight-root-get-wiring-successor-20261013/review-http-tests.txt\": \"\\\"\\\"\\\"HTTP scope fence: only the audited eight roots use installed read admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.auth import Principal, require_principal\\nfrom aos_api.errors import register_exception_handlers\\nfrom aos_api.routers import ecommerce_workshop as routes\\n\\nROOTS = {\\n    'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n    'media-studio', 'analyst', 'price-governance', 'customer',\\n}\\n\\n\\nclass RejectingCatalog:\\n    def __init__(self):\\n        self.calls = []\\n\\n    def get_readiness(self, **scope):\\n        self.calls.append(scope)\\n        raise AssetNotFoundError('not installed in current scoped catalog')\\n\\n\\ndef client_with_catalogs():\\n    app = FastAPI()\\n    register_exception_handlers(app)\\n    app.include_router(routes.router)\\n    legacy, reader = RejectingCatalog(), RejectingCatalog()\\n    app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n    app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n    app.dependency_overrides[require_principal] = lambda: Principal(\\n        subject='scope-test', org_id='org-org', project_id='dev-project',\\n        roles=['admin'], markings=[],\\n    )\\n    return TestClient(app), legacy, reader\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n    assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n\\n\\n@pytest.mark.parametrize('path', [\\n    '/views/customer/contributions', '/views/creator-growth/contributions',\\n    '/modules/ecommerce.operations/readiness',\\n])\\ndef test_unreviewed_get_still_uses_legacy_admission(path):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop' + path)\\n    assert response.status_code == 404\\n    assert legacy.calls\\n    assert not reader.calls\\n\\n\\ndef test_read_dependency_never_reaches_post_or_auxiliary_route():\\n    actual = set()\\n    for route in routes.router.routes:\\n        uses_read = any(d.call is routes.get_ecommerce_workshop_read_catalog\\n                        for d in route.dependant.dependencies)\\n        if uses_read:\\n            assert route.methods == {'GET'}\\n            actual.add(route.path)\\n    assert actual == {f'/v1/ecommerce-workshop/views/{m}' for m in ROOTS}\\n\\n\\ndef test_unknown_query_rejected_before_catalog_call():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get('/v1/ecommerce-workshop/views/operations?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\n\\nclass ReadReached(RuntimeError):\\n    pass\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_admitted_root_reaches_reader_with_authenticated_tenant(module):\\n    client, legacy, reader = client_with_catalogs()\\n    def admit(**scope):\\n        reader.calls.append(scope)\\n    reader.get_readiness = admit\\n    factory = getattr(routes, 'get_ecommerce_workshop_' + module.replace('-', '_'))\\n    class ProbeReader:\\n        def read(self, **scope):\\n            assert scope['org_id'] == 'org-org'\\n            assert scope['project_id'] == 'dev-project'\\n            raise ReadReached(module)\\n        read_core = read\\n    client.app.dependency_overrides[factory] = lambda: ProbeReader()\\n    with pytest.raises(ReadReached, match=module):\\n        client.get('/v1/ecommerce-workshop/views/' + module)\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n\\n\\ndef test_legacy_success_does_not_build_installed_configuration(monkeypatch):\\n    from aos_api import ecommerce_installed_readonly_catalog as installed\\n    sentinel = object()\\n    class Legacy:\\n        def get_readiness(self, **scope):\\n            return sentinel\\n    def forbidden():\\n        pytest.fail('successful legacy must not inspect selected configuration')\\n    monkeypatch.setattr(installed, 'build_installed_readonly_catalog', forbidden)\\n    catalog = routes.get_ecommerce_workshop_read_catalog(Legacy())\\n    assert catalog.get_readiness(module_id='ecommerce.operations') is sentinel\\n\\n\\ndef test_installed_factory_is_deferred_until_legacy_not_found(monkeypatch):\\n    from aos_api import ecommerce_installed_readonly_catalog as installed\\n    calls = []\\n    def selected():\\n        calls.append('selected')\\n        raise ValueError('configuration sentinel')\\n    monkeypatch.setattr(installed, 'build_installed_readonly_catalog', selected)\\n    catalog = routes.get_ecommerce_workshop_read_catalog(RejectingCatalog())\\n    assert not calls\\n    with pytest.raises(ValueError, match='configuration sentinel'):\\n        catalog.get_readiness(module_id='ecommerce.operations')\\n    assert calls == ['selected']\\n\", \".evidence/qyh-eight-root-get-wiring-successor-20261013/review-plan.txt\": \"# 八台 root GET 读取接线接续方案\\n\\nRules：用户 AGENTS.md、仓库 AGENTS.md、aos-engineering-delivery、231串行主计划与双侧增长产品方案、20261013完整交接；先方案后编码，单m1写者，最小变更，保护dirty，经营首链独立验收。\\n\\n## 1/8 上位复习与接管事实\\n\\n新写者 codex-01a13484-f019-7d82-94ce-812396db9124。旧写者已正式候选Delivery停工，原候选Lease释放。完整Goal已支持入口建立active；同一aos/aos-2迁移并回读到新thread，原频率/名称/通知偏好保持。Authority AOS-002012，全部强投影CURRENT，memory validate GREEN。m1 d97c4bae06e211a230efc2786eab642349fd3d9d；交接dirty清单逐项相等，两候选文件SHA一致，66日志及独立复审消费复用，不重跑已交付验证。\\n\\n原PG容器84989681fb7d3fc0f42d750672547ca0208fbba08dfef0d93837d8e64245dc3c，原权威卷aos-qyh-history159-prepared-data-20261011，18446；启动03:36:19Z。API58363/18080 cwd冻结ceba8ba4；Web58523/18434存活。最新完整重启未验收；全库指纹与页面没有在此核验中重做。39历史Lease保留；parent维护范围未归属转移，不在本Task改写/重启。\\n\\n## 2/8 文件与接口计划\\n\\n本Task qyh-eight-root-get-wiring-successor-20261013，正式Receipt/Lease当前新owner，作用域与原39 Lease无重叠。\\n\\n- services/aos-api/aos_api/routers/ecommerce_workshop.py：新增独立get_ecommerce_workshop_read_catalog/ReadCatalogDependency，仅精确8 root GET替换依赖；其余GET、readiness、POST及执行门不变。\\n- services/aos-api/aos_api/ecommerce_workshop_read_catalog.py：复用已交付候选，只有必要factory适配才追加；legacy错误、disabled、原签名/角色/租户/marking/撤销/DataScopeGrant exact不变。\\n- services/aos-api/tests/test_ecommerce_workshop_read_http.py：HTTP-specific RED→GREEN；当前安装候选授权的8 root读取，原POST/辅助与错误不放宽，无身份/跨tenant/撤销/缺scope拒绝。\\n- .evidence/qyh-eight-root-get-wiring-successor-20261013：接管验收、committed helper递归审计、RED/GREEN、原生/浏览器、冻结复审与交付证据。不得改旧证据或parent checkpoint。\\n\\n输入：当前签名selected installation ACTIVE5 + exact lock/角色/每个声明DataScopeGrant；读取AOS保留数据。输出：原业务read-model/真实blocked或unknown；不伪造runtime ready或数据，不造Run/零成功。\\n\\n先完整追踪Media.read→reader/lifecycle/publisher._compose/cumulative及其store helper，Operations.read→authority/object/inventory/aftersale/case_store。读取git HEAD中的dirty依赖，不能工作树版本混入新启动包。方法/call提取不是无副作用证明；逐个看查询及helper、连接构造和Provider/Source边界。如根路径存在未审计写/网络则不得接该route，登记缺口继续其余安全步。ReadCatalog factory复用installed原构造，不改legacy谓词。\\n\\n验证：独立HTTP RED、最小实现、专项/原HTTP相邻累计；正常SCRAM角色当前库只读与无身份/canary；最新同卷重启需单独parent归属对账后原支持路径；原owned CDP9244 SPA八页真实读取，不reload、不触动别人的tab。原POST/执行与辅助GET不得获新门。再方案代码一致性、自洽/风险及独立Prime冻结复审，合法消费，Delivery/精确m1提交/Authority和Prime同步，立即下一登记波。\\n\\n风险与回滚：readers潜在隐式写/网络、readonly unknown被误解释、dirty污染冻结；以源码递归审计+DB只读约束和真实数据验收控制。回滚限本Task确切新依赖注入，不reset/覆盖dirty、不删数据/卷/历史Lease。经营链、预算真正生效和发布仍待独立证据。\\n\\n## HTTP RED具体合同（编码前补齐）\\n\\n内容审计见read-audit-findings.md。8root范围精确为/views/{task-cockpit,operations,content-campaign,creator-growth,media-studio,analyst,price-governance,customer}。新增HTTP测试用安装读取门和legacy门独立拒绝哨兵，实际请求证明root使用新门并传递真实principal的tenant/roles/markings；辅助GET、module readiness仍legacy；路由整体遍历证明任何POST/其他GET没有新依赖。认证401及未知query400保留。此层fixture不是原生/真实经营证据，安装签名/scope adapter已交付验证不重跑；正常读取正向需后续native/browser。\\n\\n兼容复验修正：factory必须用Depends原legacy入口，不能直接调用以绕开原HTTP依赖覆盖。安装factory延迟到legacy AssetNotFound之后才构造，确保旧legacy成功时不受未配置/损坏selected配置影响；不得缓存安装结果。这是已有成功legacy保持的必要实现，追加factory专项证明错误不回退、成功不触发安装构造。\\n\", \".evidence/qyh-eight-root-get-wiring-successor-20261013/review-compatibility.txt\": \"{\\n  \\\"head\\\": \\\"d97c4bae06e211a230efc2786eab642349fd3d9d\\\",\\n  \\\"changedOriginalFunctions\\\": [\\n    \\\"get_ecommerce_workshop_operations_view\\\",\\n    \\\"get_ecommerce_workshop_content_campaign_view\\\",\\n    \\\"get_ecommerce_workshop_creator_growth_view\\\",\\n    \\\"get_ecommerce_workshop_media_studio_view\\\",\\n    \\\"get_ecommerce_workshop_analyst_view\\\",\\n    \\\"get_ecommerce_workshop_price_governance_view\\\",\\n    \\\"get_ecommerce_workshop_customer_view\\\",\\n    \\\"get_ecommerce_workshop_task_cockpit_core\\\"\\n  ],\\n  \\\"newFunctions\\\": [\\n    \\\"get_ecommerce_workshop_read_catalog\\\"\\n  ],\\n  \\\"originalOtherFunctionsAstEqual\\\": true,\\n  \\\"originalPostBodiesUnchanged\\\": true,\\n  \\\"runtimeActivated\\\": false,\\n  \\\"businessCompleted\\\": false\\n}\", \".evidence/qyh-eight-root-get-wiring-successor-20261013/review-read-catalog-r2.txt\": \"\\\"\\\"\\\"GET admission candidate over a current, signed, explicitly selected installation.\\n\\nThis adapter does not activate HTTP routes or grant runtime readiness. Legacy\\nadmission is preserved; selected installed assets require actual exact scope grants.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.ecommerce_workshop_contracts import WorkshopDependencyType\\n\\n\\nclass EcommerceWorkshopReadCatalog:\\n    def __init__(self, *, legacy, installed=None, installed_factory=None) -> None:\\n        self._legacy = legacy\\n        self._installed = installed\\n        self._installed_factory = installed_factory\\n\\n    def get_readiness(self, **scope):\\n        try:\\n            return self._legacy.get_readiness(**scope)\\n        except AssetNotFoundError:\\n            # Integrity, signature and availability errors never permit fallback.\\n            pass\\n        installed = (\\n            self._installed_factory() if self._installed_factory is not None\\n            else self._installed\\n        )\\n        result = installed.get_readiness(**scope)\\n        item = result.item\\n        installation = item.installation_ref\\n        required = set(item.permissions.data_scopes)\\n        expected_revision = (\\n            f'installation:{installation.revision}/lock:{installation.lock_revision}'\\n        )\\n        granted = {\\n            ref.resource_id for ref in item.dependency_refs\\n            if ref.resource_type == 'DataScopeGrant'\\n            and ref.revision == expected_revision\\n            and ref.content_hash == installation.lock_hash\\n            and ref.authority == 'postgres:bundle_composition_lock'\\n        }\\n        permitted_gap_types = {\\n            WorkshopDependencyType.OBJECT,\\n            WorkshopDependencyType.CAPABILITY,\\n            WorkshopDependencyType.AIP_FEATURE,\\n        }\\n        disallowed = any(\\n            blocker.dependency_type not in permitted_gap_types\\n            and not (\\n                blocker.dependency_type == WorkshopDependencyType.INSTALLATION\\n                and blocker.reason_code == 'INSTALLED_ASSET_READONLY'\\n                and blocker.dependency_id == installation.installation_id\\n            )\\n            for blocker in item.blockers\\n        )\\n        if 'ecommerce.workshop.read' not in required or not required <= granted or disallowed:\\n            raise AssetNotFoundError('Workshop module is not installed for scoped reading')\\n        # Keep the original disabled state and every runtime/authority gap intact.\\n        return result\\n\"}}"}],"timestamp":1791883625153}}
